class Animal {
    void sound() { System.out.println("Animal sound"); }
}
class Dog extends Animal {
    @Override void sound() { System.out.println("Bark"); }
}
class Cat extends Animal {
    @Override void sound() { System.out.println("Meow"); }
}
// Inside main:
Animal a1 = new Dog();
Animal a2 = new Cat();
a1.sound();
a2.sound();
